<script>
  import { splitObject } from '@splendidlabz/utils'
  import Figure from './Figure.svelte'
  const {
    class: klass = '',
    figure = true,
    picture = true,
    figureClass = '',
    caption,
    src,
    alt = '',
    width,
    height,
    loading = 'lazy',
    ...p
  } = $props()

  const figureSplit = $derived(splitObject(p, ['caption', 'captionClass']))
  const figureProps = $derived(figureSplit.p)
  const p1 = $derived(figureSplit.o)
  const pictureSplit = $derived(splitObject(p1, ['pictureClass']))
  const pictureProps = $derived(pictureSplit.p)
  const rest = $derived(pictureSplit.o)
</script>

{#snippet img()}
  <img
    class="{klass} image media"
    {alt}
    height={image.height}
    {loading}
    src={image.src}
    srcset={image.srcset}
    width={image.width}
    {...rest}
  />
{/snippet}

{#if figure}
  <Figure class={figureClass} {...figureProps}>
    {@render media()}
  </Figure>
{:else}
  {@render media()}
{/if}
